    "wrong platform",
    "root user",
    "writable root",
    "extra capability",
    "privilege escalation",
    "seccomp bypass",
    "missing data quota",
    "missing IPv4 filter",
    "missing IPv6 filter",
    "published database",
    "foreign cell data",
    "changed opaque mapping",
    "extra host mount",
    "blank evidence",
